(5894876, 859033, 23484, '<td valign="top">Nice execution. Great job on the B&amp;W.</td>', 'Nice execution. Great job on the B&W.', '2010-03-08 13:00:14.000000', NULL, 1),
(5894879, 859023, 10785, '<td valign="top">Love the blur, I just think there is too much white in the foreground. I think if the blurred people were longer and still as skinny, then it would be much better with the amount of white in the foreground.</td>', 'Love the blur, I just think there is too much white in the foreground. I think if the blurred people were longer and still as skinny, then it would be much better with the amount of white in the foreground.', '2010-03-08 13:03:38.000000', NULL, 1),
