(5894881, 858891, 99263, '<td valign="top">Striking abstract. I love the reflective sheen and the unusual shapes as well as the composition.</td>', 'Striking abstract. I love the reflective sheen and the unusual shapes as well as the composition.', '2010-03-08 13:04:26.000000', NULL, 1),
(5894884, 858875, 10785, '<td valign="top">I like the pastels and the blur!</td>', 'I like the pastels and the blur!', '2010-03-08 13:07:32.000000', NULL, 1),
(5894927, 858891, 39184, '<td valign="top">Arrggh!  This garnered one of my highest votes.  I wish that you had understood the rules about text.  Don''t let it discourage you from entering future challenges.</td>', 'Arrggh!  This garnered one of my highest votes.  I wish that you had understood the rules about text.  Don''t let it discourage you from entering future challenges.', '2010-03-08 13:30:09.000000', NULL, 1),
(5894939, 859221, 39184, '<td valign="top">Nice control of exposure.  I hope that you post the original color version in the photog''s comments.  I''d love to see it and I wonder if it would have scored better.</td>', 'Nice control of exposure.  I hope that you post the original color version in the photog''s comments.  I''d love to see it and I wonder if it would have scored better.', '2010-03-08 13:39:22.000000', NULL, 1),
