(5896966, 858793, 65234, '<td valign="top">Nicely moody with the story behind the image left to my imagination.  That''s a good thing.</td>', 'Nicely moody with the story behind the image left to my imagination.  That''s a good thing.', '2010-03-09 16:51:25.000000', NULL, 1),
(5896967, 859212, 65234, '<td valign="top">I have no idea what I''m looking at, except that there''s liquid involved.  Not knowing can be fun; I''m enjoying exploring the image.</td>', 'I have no idea what I''m looking at, except that there''s liquid involved.  Not knowing can be fun; I''m enjoying exploring the image.', '2010-03-09 16:53:36.000000', NULL, 1),
(5896968, 859138, 65234, '<td valign="top">I like the light to dark progression and the shallow DOF.  Rather dreamy effect, but the one focussed leaf looks blackened and dying.  So maybe not a good dream.  But not hopeless, since the flower on the left looks younger, like it still has a full bloom to look forward to, and to share with us.</td>', 'I like the light to dark progression and the shallow DOF.  Rather dreamy effect, but the one focussed leaf looks blackened and dying.  So maybe not a good dream.  But not hopeless, since the flower on the left looks younger, like it still has a full bloom to look forward to, and to share with us.', '2010-03-09 16:57:00.000000', NULL, 1),
(5896969, 857872, 113419, '<td valign="top">LOVELY!</td>', 'LOVELY!', '2010-03-09 16:58:14.000000', NULL, 1),
(5896973, 859213, 65234, '<td valign="top">Love the effect of the light rays coming out and bringing color with them.</td>', 'Love the effect of the light rays coming out and bringing color with them.', '2010-03-09 17:00:23.000000', NULL, 1),
(5896976, 859221, 65234, '<td valign="top">Very nice detail, but more importantly, very emotive for me.  I really like that in an image.</td>', 'Very nice detail, but more importantly, very emotive for me.  I really like that in an image.', '2010-03-09 17:01:25.000000', NULL, 1),
(5896986, 859250, 98339, '<td valign="top">great color and tones and I like your border...</td>', 'great color and tones and I like your border...', '2010-03-09 17:12:42.000000', NULL, 1),
