INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5897637, 858572, 98339, '<td valign="top">I really like your DOF, a good border on this would really top it off, another thing...I like that it''s not dead center....</td>', 'I really like your DOF, a good border on this would really top it off, another thing...I like that it''s not dead center....', '2010-03-09 23:56:45.000000', NULL, 1),
(5897642, 859035, 98339, '<td valign="top">I like the focus on the grass and the contrast with the background...but to me it seems that you could loose most of the left side of the picture without harming it at all...in fact to me it seems like it would really strengthen it</td>', 'I like the focus on the grass and the contrast with the background...but to me it seems that you could loose most of the left side of the picture without harming it at all...in fact to me it seems like it would really strengthen it', '2010-03-09 23:58:00.000000', NULL, 1),
(5897644, 858956, 98339, '<td valign="top">a bit of motion blur??? I like the color and tone of it...very abstract</td>', 'a bit of motion blur??? I like the color and tone of it...very abstract', '2010-03-09 23:58:35.000000', NULL, 1),
(5897661, 859099, 52336, '<td valign="top">I like this... you are stalking this person.  Or the scene around this person.  Or I am.  Is it fine art, or street photography?  I don''t know.  But unlike so many other photos in this challenge, this one has made me think about what it all means, and so thanks.  (Technically, I enjoy the high contrast and lovely tones, and the interesting inverse frame around the person, and then around the "No Smoking" sign.)</td>', 'I like this... you are stalking this person.  Or the scene around this person.  Or I am.  Is it fine art, or street photography?  I don''t know.  But unlike so many other photos in this challenge, this one has made me think about what it all means, and so thanks.  (Technically, I enjoy the high contrast and lovely tones, and the interesting inverse frame around the person, and then around the "No Smoking" sign.)', '2010-03-10 00:05:18.000000', NULL, 1),
(5897734, 859208, 52336, '<td valign="top">Cool.  Not fine art, of course, but cool nonetheless.  Perfect composition, and some tension between the shape of the photographer and the structure he is facing which is very pleasing.  This lens -- if it is Nikon, I would guess this is the lovely and expensive 12-24mm Nikkor.  Nice image, and very pleasing, but nothing in it to make me wonder what you were thinking when you took it.  I know what you were thinking.  The trick, for me, is to take images that make the viewer guess at what I was thinking, while knowing that I was indeed thinking *something*.</td>', 'Cool.  Not fine art, of course, but cool nonetheless.  Perfect composition, and some tension between the shape of the photographer and the structure he is facing which is very pleasing.  This lens -- if it is Nikon, I would guess this is the lovely and expensive 12-24mm Nikkor.  Nice image, and very pleasing, but nothing in it to make me wonder what you were thinking when you took it.  I know what you were thinking.  The trick, for me, is to take images that make the viewer guess at what I was thinking, while knowing that I was indeed thinking *something*.', '2010-03-10 00:19:56.000000', NULL, 1),
(5897739, 859131, 42013, '<td valign="top">Its a sleeping man with droool.</td>', 'Its a sleeping man with droool.', '2010-03-10 00:20:45.000000', NULL, 1),
(5897756, 858236, 42013, '<td valign="top">i hesitate.... but i have to ask. Of the living?</td>', 'i hesitate.... but i have to ask. Of the living?', '2010-03-10 00:26:33.000000', NULL, 1),
(5897759, 859127, 112635, '<td valign="top">excellent pp!</td>', 'excellent pp!', '2010-03-10 00:27:30.000000', NULL, 1),
(5897767, 859204, 42013, '<td valign="top">Maybe you''ll double dip the front page Ursula! :)</td>', 'Maybe you''ll double dip the front page Ursula! :)', '2010-03-10 00:28:52.000000', NULL, 1),
(5897770, 859125, 112635, '<td valign="top">dark, grungy and grainy - works for me!</td>', 'dark, grungy and grainy - works for me!', '2010-03-10 00:29:14.000000', NULL, 1),
(5897772, 859027, 52336, '<td valign="top">It''s difficult to comment on, because I don''t know what I am supposed to think.  Are you evoking pathos?  I have none.  Are you warning me?  I am unmoved.  Am I meant to be shocked?  I am a part-time naturist and I am not shocked by anyone''s naked body.  No, I don''t know what to think.  I *do* think it''s not fine art, for me, anyway.  Yes, fine art should be provocative, emotive, disturbing, or deep, or all of that, but the only sense I get from this is that the photographer tried too hard.  Technically acceptable, but I want to know what you were thinking.  I wanted to *feel* your photo.  I can only look at it though, and I can''t experience it.</td>', 'It''s difficult to comment on, because I don''t know what I am supposed to think.  Are you evoking pathos?  I have none.  Are you warning me?  I am unmoved.  Am I meant to be shocked?  I am a part-time naturist and I am not shocked by anyone''s naked body.  No, I don''t know what to think.  I *do* think it''s not fine art, for me, anyway.  Yes, fine art should be provocative, emotive, disturbing, or deep, or all of that, but the only sense I get from this is that the photographer tried too hard.  Technically acceptable, but I want to know what you were thinking.  I wanted to *feel* your photo.  I can only look at it though, and I can''t experience it.', '2010-03-10 00:30:11.000000', NULL, 1),
(5897777, 858636, 52336, '<td valign="top">Now you know the processing is over the top, don''t you?  You may *not* know that over processing is not required for good "fine art" photos.  As well, a good photo in this category would make me feel something.  But for this image, tonight, I feel nothing.  Are you in there somewhere?  Were you trying to say something?  I couldn''t see it.</td>', 'Now you know the processing is over the top, don''t you?  You may *not* know that over processing is not required for good "fine art" photos.  As well, a good photo in this category would make me feel something.  But for this image, tonight, I feel nothing.  Are you in there somewhere?  Were you trying to say something?  I couldn''t see it.', '2010-03-10 00:32:01.000000', NULL, 1),
(5897781, 858966, 42013, '<td valign="top">I love the picture--don''t know for sure if it is technically ''fine art'', whatever the heck that is... Giving it a 5 in the context of the challenge but faving it.</td>', 'I love the picture--don''t know for sure if it is technically ''fine art'', whatever the heck that is... Giving it a 5 in the context of the challenge but faving it.', '2010-03-10 00:33:04.000000', NULL, 1),
(5897783, 859027, 42013, '<td valign="top">I can see where my "American Dad" series could go if things don''t improve! :)</td>', 'I can see where my "American Dad" series could go if things don''t improve! :)', '2010-03-10 00:33:37.000000', NULL, 1),
(5897786, 858536, 52336, '<td valign="top">You in tin foil, I guess.  Whereas it''s interesting, because it''s different, it doesn''t say anything.  I would guess you didn''t know what to shoot, and so you shot this.  Because I think if you *did* know what to shoot, I would have seen it, guessed it, *felt* it.  Who are you?  I don''t know, from this.  I might want to know, depending on what type of image you''re capable of, but from this, I don''t.  Technically okay, unsharp is fine for this, white balance is off.</td>', 'You in tin foil, I guess.  Whereas it''s interesting, because it''s different, it doesn''t say anything.  I would guess you didn''t know what to shoot, and so you shot this.  Because I think if you *did* know what to shoot, I would have seen it, guessed it, *felt* it.  Who are you?  I don''t know, from this.  I might want to know, depending on what type of image you''re capable of, but from this, I don''t.  Technically okay, unsharp is fine for this, white balance is off.', '2010-03-10 00:34:41.000000', NULL, 1),
(5897798, 858897, 52336, '<td valign="top">I''m sorry, simply not "fine art".  This is a portrait, and would not work as fine art.  I don''t know her, and through her, I fail to understand you.  My favourite fine art pictures force me to think in ways the photographer wants me to think, or to see that which is otherwise unviewable.  I don''t necessarily mean in terms of subject matter or the accessibility of the components of the image, but in that invested by the photographer in the image.  I know what this is.  It''s a portrait.  Technically, it needs lots of work; the sharpening did not work.  The lighting is poor, and so the image is "flat".  The tones are not good.  Please try again, should there be another "fine art" challenge.  Tell me something I don''t already know.</td>', 'I''m sorry, simply not "fine art".  This is a portrait, and would not work as fine art.  I don''t know her, and through her, I fail to understand you.  My favourite fine art pictures force me to think in ways the photographer wants me to think, or to see that which is otherwise unviewable.  I don''t necessarily mean in terms of subject matter or the accessibility of the components of the image, but in that invested by the photographer in the image.  I know what this is.  It''s a portrait.  Technically, it needs lots of work; the sharpening did not work.  The lighting is poor, and so the image is "flat".  The tones are not good.  Please try again, should there be another "fine art" challenge.  Tell me something I don''t already know.', '2010-03-10 00:38:25.000000', NULL, 1),
(5897816, 858897, 112635, '<td valign="top">nice.. extra points for props</td>', 'nice.. extra points for props', '2010-03-10 00:43:53.000000', NULL, 1),
