(5898570, 859204, 99506, '<td valign="top">clever title and affective image</td>', 'clever title and affective image', '2010-03-10 12:53:47.000000', NULL, 1),
(5898573, 859247, 99506, '<td valign="top">Am I deceived ot just confused? lol</td>', 'Am I deceived ot just confused? lol', '2010-03-10 12:54:37.000000', NULL, 1),
(5898594, 858694, 64568, '<td valign="top">Would be a pleasure to have this hanging on my wall, great shot.</td>', 'Would be a pleasure to have this hanging on my wall, great shot.', '2010-03-10 13:05:02.000000', NULL, 1),
(5898595, 858654, 64568, '<td valign="top">Top 3 for me, wonderful shot with great imagination</td>', 'Top 3 for me, wonderful shot with great imagination', '2010-03-10 13:05:48.000000', NULL, 1),
(5898600, 857967, 64568, '<td valign="top">This like another I commented on, would be a pleasue to hang on my wall, simple and beautiful.</td>', 'This like another I commented on, would be a pleasue to hang on my wall, simple and beautiful.', '2010-03-10 13:06:46.000000', NULL, 1),
(5898601, 859242, 64568, '<td valign="top">Great colours and motion, really pleasing to the eye.</td>', 'Great colours and motion, really pleasing to the eye.', '2010-03-10 13:07:18.000000', NULL, 1),
(5898602, 859247, 64568, '<td valign="top">wondefully strange, back to bump up</td>', 'wondefully strange, back to bump up', '2010-03-10 13:08:05.000000', NULL, 1),
(5898603, 859022, 64568, '<td valign="top">Great shot, another which I would hang on my wall gladly. Bumped up after 5th look ;-)</td>', 'Great shot, another which I would hang on my wall gladly. Bumped up after 5th look ;-)', '2010-03-10 13:09:15.000000', NULL, 1),
(5898647, 859248, 11920, '<td valign="top">I cant vote but I would certainly put this on my wall.</td>', 'I cant vote but I would certainly put this on my wall.', '2010-03-10 13:44:06.000000', NULL, 1),
(5898858, 858744, 44025, '<td valign="top">I think th eimage needs to be slightly brighter</td>', 'I think th eimage needs to be slightly brighter', '2010-03-10 16:01:05.000000', NULL, 1),
(5898862, 859191, 44025, '<td valign="top">Too much sky. Rules of third should have been applied.</td>', 'Too much sky. Rules of third should have been applied.', '2010-03-10 16:05:09.000000', NULL, 1),
(5898864, 858472, 44025, '<td valign="top">Good photgraph, but the subject doesn''t do it for me</td>', 'Good photgraph, but the subject doesn''t do it for me', '2010-03-10 16:09:57.000000', NULL, 1),
(5898883, 859143, 61961, '<td valign="top">My canned response: whatever one''s definition is of fine/contemporary/modern art, I think this entry is too much like business as usual at DPC.  In this case: a seascape, long exposure to make water silky.<br/> <br/>However, I like the combo of blur with the mostly silhouetted figure, and the three little ships on the horizon are interesting.</td>', 'My canned response: whatever one''s definition is of fine/contemporary/modern art, I think this entry is too much like business as usual at DPC.  In this case: a seascape, long exposure to make water silky. However, I like the combo of blur with the mostly silhouetted figure, and the three little ships on the horizon are interesting.', '2010-03-10 16:27:28.000000', NULL, 1),
(5898893, 857870, 61961, '<td valign="top">My canned response: whatever one''s definition is of fine/contemporary/modern art, I think this entry is too much like business as usual at DPC.  In this case: a flower photo, desat background.  Nothing new enough, despite addition of some interesting props.<br/> <br/>I like however the floor surface.  It almost looks like an overlay.</td>', 'My canned response: whatever one''s definition is of fine/contemporary/modern art, I think this entry is too much like business as usual at DPC.  In this case: a flower photo, desat background.  Nothing new enough, despite addition of some interesting props. I like however the floor surface.  It almost looks like an overlay.', '2010-03-10 16:33:02.000000', NULL, 1),
(5898894, 859246, 104841, '<td valign="top">good angle to shoot these bridges from, for the feel you are going for though I would consider removing the clouds though.</td>', 'good angle to shoot these bridges from, for the feel you are going for though I would consider removing the clouds though.', '2010-03-10 16:33:24.000000', NULL, 1),
(5898899, 858615, 61961, '<td valign="top">At first, I was going to give you my canned response: that whatever one''s definition is of fine/contemporary/modern art, I think this entry is too much like business as usual at DPC: another bird photo!  But it strikes me that by giving this such an old-fashioned look, you may have actually created something new, or or at least on the path.</td>', 'At first, I was going to give you my canned response: that whatever one''s definition is of fine/contemporary/modern art, I think this entry is too much like business as usual at DPC: another bird photo!  But it strikes me that by giving this such an old-fashioned look, you may have actually created something new, or or at least on the path.', '2010-03-10 16:35:43.000000', NULL, 1),
(5898901, 859125, 61961, '<td valign="top">I can imagine this hanging in a gallery show.</td>', 'I can imagine this hanging in a gallery show.', '2010-03-10 16:37:09.000000', NULL, 1),
(5898903, 858862, 61961, '<td valign="top">Fetishistic!  Interesting photo.  I''m not crazy about desat in general and the bright red nails are maybe a touch overdone, but I think your entry needed something quirky (in addition to the subject), so maybe the color was the best way to go.</td>', 'Fetishistic!  Interesting photo.  I''m not crazy about desat in general and the bright red nails are maybe a touch overdone, but I think your entry needed something quirky (in addition to the subject), so maybe the color was the best way to go.', '2010-03-10 16:39:58.000000', NULL, 1),
(5898906, 859227, 61961, '<td valign="top">My canned response: whatever one''s definition is of fine/contemporary/modern art, I think this entry is too much like business as usual at DPC.  In this case: a flower photo.  I think it is gorgeous, with great color and clarity, and I like how the stem is lit.  I''d have no problem giving it high points in a free study.  Still, I give you points for turning it upside down. :-)</td>', 'My canned response: whatever one''s definition is of fine/contemporary/modern art, I think this entry is too much like business as usual at DPC.  In this case: a flower photo.  I think it is gorgeous, with great color and clarity, and I like how the stem is lit.  I''d have no problem giving it high points in a free study.  Still, I give you points for turning it upside down. :-)', '2010-03-10 16:42:50.000000', NULL, 1),
(5898909, 859252, 61961, '<td valign="top">Speaking subjectively, I think you are right on target with what this challenge requested.  Excellent and original.  A bit spooky, too.  This viewer asks: Is there a face?</td>', 'Speaking subjectively, I think you are right on target with what this challenge requested.  Excellent and original.  A bit spooky, too.  This viewer asks: Is there a face?', '2010-03-10 16:45:59.000000', NULL, 1),
(5898911, 859162, 61961, '<td valign="top">OK, you got me.  You took a flower photo and then made it contemporary.  Beautiful tones, and I love how the background is strong but doesn''t overwhelm the foreground.</td>', 'OK, you got me.  You took a flower photo and then made it contemporary.  Beautiful tones, and I love how the background is strong but doesn''t overwhelm the foreground.', '2010-03-10 16:47:17.000000', NULL, 1),
(5898913, 858940, 61961, '<td valign="top">Nice.  I immediately thought of the twin towers (in New York, not in The Lord of the Rings).  The grain could be a cloud.  Something militaristic or at least bullet-like about the chopsticks.  OMG, is that skin?  Better and better.</td>', 'Nice.  I immediately thought of the twin towers (in New York, not in The Lord of the Rings).  The grain could be a cloud.  Something militaristic or at least bullet-like about the chopsticks.  OMG, is that skin?  Better and better.', '2010-03-10 16:50:08.000000', NULL, 1),
(5898916, 859095, 109309, '<td valign="top">I like theis scene, but I don''t think the texture adds anything to it.</td>', 'I like theis scene, but I don''t think the texture adds anything to it.', '2010-03-10 16:51:40.000000', NULL, 1),
(5898922, 859118, 109309, '<td valign="top">Potentially a good Photo, The treatment does not work for me though.</td>', 'Potentially a good Photo, The treatment does not work for me though.', '2010-03-10 17:00:05.000000', NULL, 1),
(5898933, 859054, 61961, '<td valign="top">Very pretty, with fantastic colors, and I like the blur placements.  However, a little too much DPC business-as-usual for the challenge.  I don''t see an attempt to bring anything new.</td>', 'Very pretty, with fantastic colors, and I like the blur placements.  However, a little too much DPC business-as-usual for the challenge.  I don''t see an attempt to bring anything new.', '2010-03-10 17:09:43.000000', NULL, 1),
(5898960, 859027, 61961, '<td valign="top">Remarkable.  Grabs the challenge theme by the (thankfully not visible) balls.  This would make a fantastic series.  So powerful.  OK, I''m probably going overboard, so I''ll just vote.</td>', 'Remarkable.  Grabs the challenge theme by the (thankfully not visible) balls.  This would make a fantastic series.  So powerful.  OK, I''m probably going overboard, so I''ll just vote.', '2010-03-10 17:24:15.000000', NULL, 1),
(5899006, 858767, 109309, '<td valign="top">Interesting and unique.</td>', 'Interesting and unique.', '2010-03-10 18:03:51.000000', NULL, 1),
(5899008, 859209, 109309, '<td valign="top">Beautiful</td>', 'Beautiful', '2010-03-10 18:04:22.000000', NULL, 1),
(5899023, 859169, 109309, '<td valign="top">Nice abstract</td>', 'Nice abstract', '2010-03-10 18:16:34.000000', NULL, 1),
(5899032, 858479, 109309, '<td valign="top">I like the lines and the simplicity</td>', 'I like the lines and the simplicity', '2010-03-10 18:18:53.000000', NULL, 1),
(5899037, 859004, 63218, '<td valign="top">What caught my eye right away was the combination of colors. Sweet. Then, the vignette puts a spotlight on the wierd subject. Usually I don''t like vignette''s but this one works. These little whatever-they-are-entities are so quixotic &amp; cute, I can''t help but like them.</td>', 'What caught my eye right away was the combination of colors. Sweet. Then, the vignette puts a spotlight on the wierd subject. Usually I don''t like vignette''s but this one works. These little whatever-they-are-entities are so quixotic & cute, I can''t help but like them.', '2010-03-10 18:22:54.000000', NULL, 1),
(5899041, 858472, 52336, '<td valign="top">Jokey, and therefore not "fine art", as you know.  I like photos when I connect with them, or they tell some kind of story I didn''t know about.  I consider something "fine art" when it is obliquely metaphoric, when the message is layered, or emotive or unsettling, or all of these.  Much of what is produced at DPC has a broad base of appeal (humourous images amongst them); this challenge sought to explore a different side to DPC, one largely unnoticed by most.  In my view, it was inviting images that were communicative in some moving way, that weren''t facile.</td>', 'Jokey, and therefore not "fine art", as you know.  I like photos when I connect with them, or they tell some kind of story I didn''t know about.  I consider something "fine art" when it is obliquely metaphoric, when the message is layered, or emotive or unsettling, or all of these.  Much of what is produced at DPC has a broad base of appeal (humourous images amongst them); this challenge sought to explore a different side to DPC, one largely unnoticed by most.  In my view, it was inviting images that were communicative in some moving way, that weren''t facile.', '2010-03-10 18:23:45.000000', NULL, 1),
(5899044, 859248, 63218, '<td valign="top">...&amp; moving on. The blur adds to the storytelling. I wonder, are those the bright lights of the future on the horizon?</td>', '...& moving on. The blur adds to the storytelling. I wonder, are those the bright lights of the future on the horizon?', '2010-03-10 18:25:11.000000', NULL, 1),
(5899045, 858395, 52336, '<td valign="top">Your photo is very manipulative, and I find it troubling for that reason.  I don''t consider it fine art.  Whereas it''s true that many fine art photos seek to be emotive, or to communicate a message that the photographer wants the viewer to know about, this photo, for me, doesn''t do that.  Instead, my reaction to it is thought to be predetermined.  I would rather know who you are, through your imagery.  Perhaps it''s in this image, perhaps not, but I feel somewhat manipulated by this, and can''t say for sure.</td>', 'Your photo is very manipulative, and I find it troubling for that reason.  I don''t consider it fine art.  Whereas it''s true that many fine art photos seek to be emotive, or to communicate a message that the photographer wants the viewer to know about, this photo, for me, doesn''t do that.  Instead, my reaction to it is thought to be predetermined.  I would rather know who you are, through your imagery.  Perhaps it''s in this image, perhaps not, but I feel somewhat manipulated by this, and can''t say for sure.', '2010-03-10 18:26:06.000000', NULL, 1),
(5899047, 859122, 63218, '<td valign="top">Takes me right back to my childhood, &amp; playing dressup.</td>', 'Takes me right back to my childhood, & playing dressup.', '2010-03-10 18:26:42.000000', NULL, 1),
(5899049, 859207, 12733, '<td valign="top">I see the point, but it starts to get very busy, with the hanging instruments and the harsh lighting on the player.</td>', 'I see the point, but it starts to get very busy, with the hanging instruments and the harsh lighting on the player.', '2010-03-10 18:27:37.000000', NULL, 1),
(5899054, 859022, 12733, '<td valign="top">It''s an interesting picture, but fine art?  The contrast seems very harsh. Is this a negative???</td>', 'It''s an interesting picture, but fine art?  The contrast seems very harsh. Is this a negative???', '2010-03-10 18:28:37.000000', NULL, 1),
(5899055, 859099, 12733, '<td valign="top">I can see this illustrating a magazine ad or story about drugs, loneliness or similar, but fine art?</td>', 'I can see this illustrating a magazine ad or story about drugs, loneliness or similar, but fine art?', '2010-03-10 18:29:39.000000', NULL, 1),
(5899057, 859111, 52336, '<td valign="top">Unfortunately not fine art, in my opinion.  Who are you?  What are you saying with your image?  What should I feel about the things you''re saying?  Does it mean anything to you?  Are you in here, somewhere?  Those are the questions I want answered by a photograph in a challenge such as this.  Technically your image is very dark, and needs levels adjustments in post.  The lighting is not good.  The tight crop/frame is not the best; perhaps a shot of the entire plant might have made for a more engaging or delicate picture.</td>', 'Unfortunately not fine art, in my opinion.  Who are you?  What are you saying with your image?  What should I feel about the things you''re saying?  Does it mean anything to you?  Are you in here, somewhere?  Those are the questions I want answered by a photograph in a challenge such as this.  Technically your image is very dark, and needs levels adjustments in post.  The lighting is not good.  The tight crop/frame is not the best; perhaps a shot of the entire plant might have made for a more engaging or delicate picture.', '2010-03-10 18:30:21.000000', NULL, 1),
(5899058, 858943, 12733, '<td valign="top">Good thing I rate photos, not titles.</td>', 'Good thing I rate photos, not titles.', '2010-03-10 18:30:39.000000', NULL, 1),
(5899060, 859223, 12733, '<td valign="top">Nice use of zoom. I get dizzy if I look at this too long.</td>', 'Nice use of zoom. I get dizzy if I look at this too long.', '2010-03-10 18:31:44.000000', NULL, 1),
(5899061, 858694, 52336, '<td valign="top">I don''t actually get the Hinomaru from this image.  At any rate, abstraction may work as fine art, but here it does not, in my opinion.  I enjoy messages from photos considered to be fine art.  They don''t have to be deep messages, and certainly shouldn''t be obvious, but something must be said.  What''s being said here?</td>', 'I don''t actually get the Hinomaru from this image.  At any rate, abstraction may work as fine art, but here it does not, in my opinion.  I enjoy messages from photos considered to be fine art.  They don''t have to be deep messages, and certainly shouldn''t be obvious, but something must be said.  What''s being said here?', '2010-03-10 18:32:34.000000', NULL, 1),
(5899062, 858538, 23484, '<td valign="top">Very nice idea and good job with it.</td>', 'Very nice idea and good job with it.', '2010-03-10 18:32:56.000000', NULL, 1),
(5899064, 858744, 23484, '<td valign="top">Great image. I really like the idea and you did such a good job executing it. No pun intended. The lighting is very nice.</td>', 'Great image. I really like the idea and you did such a good job executing it. No pun intended. The lighting is very nice.', '2010-03-10 18:34:07.000000', NULL, 1),
(5899068, 859122, 23484, '<td valign="top">Very strange looking but I like the idea. Very nicely done.</td>', 'Very strange looking but I like the idea. Very nicely done.', '2010-03-10 18:34:51.000000', NULL, 1),
(5899069, 858808, 12733, '<td valign="top">The sign makes it a better landscape photo, but also pulls it out of the fine art category.</td>', 'The sign makes it a better landscape photo, but also pulls it out of the fine art category.', '2010-03-10 18:35:08.000000', NULL, 1),
(5899070, 857856, 69325, '<td valign="top">bulky title, the shot should mostly be able to speak for itself, no need to tell us about your editing steps, or lack thereof.</td>', 'bulky title, the shot should mostly be able to speak for itself, no need to tell us about your editing steps, or lack thereof.', '2010-03-10 18:35:24.000000', NULL, 1),
(5899073, 859225, 23484, '<td valign="top">I like the idea of using an adult as the model instead of a child. Nice lighting and shadows.</td>', 'I like the idea of using an adult as the model instead of a child. Nice lighting and shadows.', '2010-03-10 18:35:56.000000', NULL, 1),
(5899081, 859122, 12733, '<td valign="top">Very funny, a photo cartoon!</td>', 'Very funny, a photo cartoon!', '2010-03-10 18:38:53.000000', NULL, 1),
(5899082, 859177, 23484, '<td valign="top">Well composed and processed. I like the grain.</td>', 'Well composed and processed. I like the grain.', '2010-03-10 18:39:33.000000', NULL, 1),
(5899084, 859204, 12733, '<td valign="top">I love the sense of motion.</td>', 'I love the sense of motion.', '2010-03-10 18:40:37.000000', NULL, 1),
(5899085, 859039, 23484, '<td valign="top">Very nice letter representation. The look of the snow falling is a neat effect.</td>', 'Very nice letter representation. The look of the snow falling is a neat effect.', '2010-03-10 18:40:39.000000', NULL, 1),
(5899088, 859081, 23484, '<td valign="top">The diagonal shadows are neat. Goes well with the image.</td>', 'The diagonal shadows are neat. Goes well with the image.', '2010-03-10 18:41:41.000000', NULL, 1),
(5899089, 859084, 23484, '<td valign="top">Neat abstract style image. Love the grain.</td>', 'Neat abstract style image. Love the grain.', '2010-03-10 18:42:08.000000', NULL, 1),
(5899090, 858968, 23484, '<td valign="top">Almost looks like a guitar. But then again, I could be wrong. Nice image.</td>', 'Almost looks like a guitar. But then again, I could be wrong. Nice image.', '2010-03-10 18:43:02.000000', NULL, 1),
(5899092, 858967, 23484, '<td valign="top">Nice job. The shadow is great. That damn cube drove me nuts for a long time.</td>', 'Nice job. The shadow is great. That damn cube drove me nuts for a long time.', '2010-03-10 18:44:25.000000', NULL, 1),
(5899093, 858768, 23484, '<td valign="top">Very dramatic and wild looking.</td>', 'Very dramatic and wild looking.', '2010-03-10 18:46:10.000000', NULL, 1),
(5899094, 859127, 23484, '<td valign="top">Fantastic image. I love the subject, the processing and the composition. I''m not real fond of the border but it''s still worth a 10 in my book.</td>', 'Fantastic image. I love the subject, the processing and the composition. I''m not real fond of the border but it''s still worth a 10 in my book.', '2010-03-10 18:47:19.000000', NULL, 1),
(5899096, 857967, 23484, '<td valign="top">You know, I kind of miss the old vinyl. Very nice title and great image.</td>', 'You know, I kind of miss the old vinyl. Very nice title and great image.', '2010-03-10 18:48:33.000000', NULL, 1),
(5899097, 858862, 23484, '<td valign="top">Now there''s a unique idea and this is my next to last image in voting.  Saved one of the best for the end I guess. Great job. 10</td>', 'Now there''s a unique idea and this is my next to last image in voting.  Saved one of the best for the end I guess. Great job. 10', '2010-03-10 18:49:44.000000', NULL, 1),
(5899101, 859248, 23484, '<td valign="top">Absolutely magnificent. 10<br/> <br/>eta: I wish I could have given this 11. I''m all done voting and this is my favorite.</td>', 'Absolutely magnificent. 10 eta: I wish I could have given this 11. I''m all done voting and this is my favorite.', '2010-03-10 18:51:58.000000', NULL, 1),
(5899106, 858968, 63218, '<td valign="top">The handle of that fork (?) caught my eye right away. Very nice. The colors are a bit odd, but IMO the whole thing works because of the red in the upper R corner. Camera-motion blur is what this looks like to me, &amp; I like it!</td>', 'The handle of that fork (?) caught my eye right away. Very nice. The colors are a bit odd, but IMO the whole thing works because of the red in the upper R corner. Camera-motion blur is what this looks like to me, & I like it!', '2010-03-10 18:57:12.000000', NULL, 1),
(5899155, 859247, 30982, '<td valign="top">Cat dancing is a lost art.  Or at least one we rarely see in the daylight; I suspect there are hootenannies held in the dark in faraway places...</td>', 'Cat dancing is a lost art.  Or at least one we rarely see in the daylight; I suspect there are hootenannies held in the dark in faraway places...', '2010-03-10 19:44:49.000000', NULL, 1),
(5899160, 859248, 30982, '<td valign="top">Grown up but not ready to let go just yet, it seems.  I like the androgynous nature of the subject.</td>', 'Grown up but not ready to let go just yet, it seems.  I like the androgynous nature of the subject.', '2010-03-10 19:46:02.000000', NULL, 1),
(5899162, 859144, 30982, '<td valign="top">I may be odd, but this is delightfully playful.  I see a little green inchworm having a blast.</td>', 'I may be odd, but this is delightfully playful.  I see a little green inchworm having a blast.', '2010-03-10 19:46:34.000000', NULL, 1),
(5899164, 858913, 30982, '<td valign="top">Wonderfully odd and nice in B&amp;W!</td>', 'Wonderfully odd and nice in B&W!', '2010-03-10 19:46:55.000000', NULL, 1),
(5899165, 859143, 30982, '<td valign="top">Were one to so desire, one could attach religious significance to this - a fisher of men, the three Magi in the distance.  Mostly, though, it''s a lovely quiet presentation of the stillness and wonder of morning.</td>', 'Were one to so desire, one could attach religious significance to this - a fisher of men, the three Magi in the distance.  Mostly, though, it''s a lovely quiet presentation of the stillness and wonder of morning.', '2010-03-10 19:48:15.000000', NULL, 1),
(5899166, 858813, 30982, '<td valign="top">Clever, unusual, and makes me wonder.</td>', 'Clever, unusual, and makes me wonder.', '2010-03-10 19:48:29.000000', NULL, 1),
(5899167, 858236, 30982, '<td valign="top">Fascinating both as a subject and as a photograph.  Textures, light, color/toning all work.</td>', 'Fascinating both as a subject and as a photograph.  Textures, light, color/toning all work.', '2010-03-10 19:49:10.000000', NULL, 1),
(5899168, 858551, 30982, '<td valign="top">An excellent title as it does indeed both conjure and capture those who''ve passed this way in their many forms.</td>', 'An excellent title as it does indeed both conjure and capture those who''ve passed this way in their many forms.', '2010-03-10 19:53:01.000000', NULL, 1),
(5899169, 859022, 30982, '<td valign="top">Has a sense of timeless repetition, a nameless and faceless dance that takes place everywhere, every day.</td>', 'Has a sense of timeless repetition, a nameless and faceless dance that takes place everywhere, every day.', '2010-03-10 19:53:49.000000', NULL, 1),
(5899170, 859027, 83686, '<td valign="top">a bit too extreme for my tastes</td>', 'a bit too extreme for my tastes', '2010-03-10 19:53:52.000000', NULL, 1),
(5899171, 858802, 30982, '<td valign="top">As the printed page begins to fade...</td>', 'As the printed page begins to fade...', '2010-03-10 19:54:13.000000', NULL, 1),
(5899172, 858485, 83686, '<td valign="top">lighting and colors seem odd to me</td>', 'lighting and colors seem odd to me', '2010-03-10 19:54:29.000000', NULL, 1),
(5899174, 858917, 30982, '<td valign="top">Absurd and quite wonderfully captured.</td>', 'Absurd and quite wonderfully captured.', '2010-03-10 19:54:36.000000', NULL, 1),
(5899176, 859145, 30982, '<td valign="top">The hand is recognizable as such yet has formed something entirely out of its original scope and part of the background.</td>', 'The hand is recognizable as such yet has formed something entirely out of its original scope and part of the background.', '2010-03-10 19:55:11.000000', NULL, 1),
(5899177, 859141, 83686, '<td valign="top">not sure how this is done, very different</td>', 'not sure how this is done, very different', '2010-03-10 19:55:19.000000', NULL, 1),
(5899178, 858773, 83686, '<td valign="top">my eyes have a hard time looking at this...</td>', 'my eyes have a hard time looking at this...', '2010-03-10 19:55:46.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5899180, 858636, 83686, '<td valign="top">not really something I would hang, very noisy background</td>', 'not really something I would hang, very noisy background', '2010-03-10 19:56:27.000000', NULL, 1),
