(5899566, 859096, 99263, '<td valign="top">Hmmmm...a mystery. Where are the happy picnicking couple? Abducted by aliens? Did a murder most foul take place here? Or are they perhaps being passionate in the undergrowth? Whatever...it''s a beautifully executed image with wonderful lighting.</td>', 'Hmmmm...a mystery. Where are the happy picnicking couple? Abducted by aliens? Did a murder most foul take place here? Or are they perhaps being passionate in the undergrowth? Whatever...it''s a beautifully executed image with wonderful lighting.', '2010-03-11 02:03:49.000000', NULL, 1),
(5899568, 859028, 99263, '<td valign="top">Creative and artistic.</td>', 'Creative and artistic.', '2010-03-11 02:04:19.000000', NULL, 1),
(5899569, 859144, 99263, '<td valign="top">Eye catching and artistically executed abstract.</td>', 'Eye catching and artistically executed abstract.', '2010-03-11 02:04:26.000000', NULL, 1),
(5899571, 859204, 99263, '<td valign="top">Beautifully rendered. I have a suspicion this might be by Ursula as it reminds me of her recent Yin&amp;Yang image.</td>', 'Beautifully rendered. I have a suspicion this might be by Ursula as it reminds me of her recent Yin&Yang image.', '2010-03-11 02:05:08.000000', NULL, 1),
(5899573, 859124, 99263, '<td valign="top">Wonderful effect that gives the image a dreamy look as if it''s a memory of a summer gone by.</td>', 'Wonderful effect that gives the image a dreamy look as if it''s a memory of a summer gone by.', '2010-03-11 02:05:33.000000', NULL, 1),
