(5899626, 858282, 35545, '<td valign="top">Elegant.</td>', 'Elegant.', '2010-03-11 03:44:14.000000', NULL, 1),
(5899651, 859144, 86799, '<td valign="top">Simple and pure, wonderful lines and color and texture.  Enough good stuff to hold attention.  This would be nice BIG and hanging.</td>', 'Simple and pure, wonderful lines and color and texture.  Enough good stuff to hold attention.  This would be nice BIG and hanging.', '2010-03-11 06:06:29.000000', NULL, 1),
(5899706, 857780, 76585, '<td valign="top">Would love to see this in bw, still a 10 for me. By far one of the best in the challenge. Perfect composition, nice work!</td>', 'Would love to see this in bw, still a 10 for me. By far one of the best in the challenge. Perfect composition, nice work!', '2010-03-11 07:56:52.000000', NULL, 1),
