(5899712, 859213, 76585, '<td valign="top">Love this!!! What did it look like in bw? 10</td>', 'Love this!!! What did it look like in bw? 10', '2010-03-11 08:06:06.000000', NULL, 1),
(5899713, 859187, 80908, '<td valign="top">Interesting composition. Nice use of blur but could have done without the noise right in the centre IMHO. Good OOB stuff.</td>', 'Interesting composition. Nice use of blur but could have done without the noise right in the centre IMHO. Good OOB stuff.', '2010-03-11 08:11:16.000000', NULL, 1),
(5899714, 859156, 80908, '<td valign="top">Lovely textures and a striking composition, but the offset angle of the bolt doesn''t sit quite right for this. Also seems a little over-sharpened / topaz''d? Since the colour is not as important to this as the textures and contrasts, I''d be interested to see a BW version perhaps with a burnt vignette to focus the attention on the bolt.</td>', 'Lovely textures and a striking composition, but the offset angle of the bolt doesn''t sit quite right for this. Also seems a little over-sharpened / topaz''d? Since the colour is not as important to this as the textures and contrasts, I''d be interested to see a BW version perhaps with a burnt vignette to focus the attention on the bolt.', '2010-03-11 08:13:30.000000', NULL, 1),
(5899717, 858914, 76585, '<td valign="top">Nice lines and perspective, definitely architectural fine art, would love to see it in bw.8</td>', 'Nice lines and perspective, definitely architectural fine art, would love to see it in bw.8', '2010-03-11 08:13:47.000000', NULL, 1),
(5899718, 858538, 80908, '<td valign="top">Lovely composition. Unusually, the broken / textured background in this case adds rather than detracts from the image for me. Very artistic.</td>', 'Lovely composition. Unusually, the broken / textured background in this case adds rather than detracts from the image for me. Very artistic.', '2010-03-11 08:14:47.000000', NULL, 1),
(5899720, 859038, 80908, '<td valign="top">The original shot is beautifully composed, and the expression is priceless! The treatment does not appeal to me unfortunately - I would bet that this shot would be just fine without it.</td>', 'The original shot is beautifully composed, and the expression is priceless! The treatment does not appeal to me unfortunately - I would bet that this shot would be just fine without it.', '2010-03-11 08:16:16.000000', NULL, 1),
(5899721, 858968, 76585, '<td valign="top">This is a beautiful blur, love it. 10</td>', 'This is a beautiful blur, love it. 10', '2010-03-11 08:17:14.000000', NULL, 1),
(5899722, 858339, 80908, '<td valign="top">Beautiful tone across the whole, excellently composed shot. I would not have seen the lady without the title - but she is definitely there! Classic but fresh. Great work.</td>', 'Beautiful tone across the whole, excellently composed shot. I would not have seen the lady without the title - but she is definitely there! Classic but fresh. Great work.', '2010-03-11 08:18:23.000000', NULL, 1),
(5899723, 859217, 80908, '<td valign="top">Interesting, and nicely composed, but the strength of the lighting on the background compared to the subject keeps dragging my eye away. The jagged shadow below the flower is also distracting - more light here would really make the ''promise'' pop.</td>', 'Interesting, and nicely composed, but the strength of the lighting on the background compared to the subject keeps dragging my eye away. The jagged shadow below the flower is also distracting - more light here would really make the ''promise'' pop.', '2010-03-11 08:20:28.000000', NULL, 1),
(5899724, 859176, 76585, '<td valign="top">Love this!!!</td>', 'Love this!!!', '2010-03-11 08:21:21.000000', NULL, 1),
(5899725, 858297, 80908, '<td valign="top">Interesting. The noise gives it a slight Warhol feel, which doesn''t appeal to my artistic tastes (such as they are!) but assuming this was what was shot for - you definitely got it. So good job!</td>', 'Interesting. The noise gives it a slight Warhol feel, which doesn''t appeal to my artistic tastes (such as they are!) but assuming this was what was shot for - you definitely got it. So good job!', '2010-03-11 08:22:14.000000', NULL, 1),
