(5899754, 859123, 9780, '<td valign="top">OUTSTANDING PHOTO!</td>', 'OUTSTANDING PHOTO!', '2010-03-11 08:45:31.000000', NULL, 1),
(5899762, 859027, 51269, '<td valign="top">The model actually looks quite good &amp; not elderly . The expression , lank hair &amp; beard plus the oxygen, make me think "depression". Well executed image.</td>', 'The model actually looks quite good & not elderly . The expression , lank hair & beard plus the oxygen, make me think "depression". Well executed image.', '2010-03-11 08:51:28.000000', NULL, 1),
(5899764, 858626, 80908, '<td valign="top">Lovely moody shot - unusual point of view too. For a moment I thought that those were people in the middle. Reall nice balance</td>', 'Lovely moody shot - unusual point of view too. For a moment I thought that those were people in the middle. Reall nice balance', '2010-03-11 08:56:23.000000', NULL, 1),
