(5901052, 858875, 50641, '<td valign="top">gauzy goodness!</td>', 'gauzy goodness!', '2010-03-12 09:53:30.000000', NULL, 1),
(5901053, 859057, 50641, '<td valign="top">i like the twinning of deformities, vase and flower</td>', 'i like the twinning of deformities, vase and flower', '2010-03-12 09:53:34.000000', NULL, 1),
(5901059, 859084, 104230, '<td valign="top">I like this, although as yet I cannot really articulate exactly why. Interesting lines and textures for sure. On the technical side I think you either used a lens baby or blurred quite a large area around the edge some other way.  The sudden transition from blur to sharp near the front banana favors the latter theory.</td>', 'I like this, although as yet I cannot really articulate exactly why. Interesting lines and textures for sure. On the technical side I think you either used a lens baby or blurred quite a large area around the edge some other way.  The sudden transition from blur to sharp near the front banana favors the latter theory.', '2010-03-12 10:00:02.000000', NULL, 1),
(5901060, 858600, 50641, '<td valign="top">nice scene. birds a little crunchy but can call that a stylistic choice ;-)</td>', 'nice scene. birds a little crunchy but can call that a stylistic choice ;-)', '2010-03-12 10:01:40.000000', NULL, 1);
