(5901834, 859100, 18505, '<td valign="top">Just beautiful...  Good luck in the challenge.</td>', 'Just beautiful...  Good luck in the challenge.', '2010-03-12 20:33:52.000000', NULL, 1),
(5901837, 858966, 18505, '<td valign="top">Excellent capture.  I love his happy expression and protective posture, and her tentative, less trusting, yet very direct gaze.</td>', 'Excellent capture.  I love his happy expression and protective posture, and her tentative, less trusting, yet very direct gaze.', '2010-03-12 20:36:33.000000', NULL, 1),
(5901845, 859118, 18505, '<td valign="top">I really like this.  Everything from the graduated tones, to the crow''s posture and clenched claws, to the red eye evokes a feeling of mystery and doom.  The title is priceless!!!  <strike>good</strike> great work.</td>', 'I really like this.  Everything from the graduated tones, to the crow''s posture and clenched claws, to the red eye evokes a feeling of mystery and doom.  The title is priceless!!!  good great work.', '2010-03-12 20:40:52.000000', NULL, 1),
(5901846, 858137, 18505, '<td valign="top">I love the textures and the earthy colors in this one.  Beautiful!</td>', 'I love the textures and the earthy colors in this one.  Beautiful!', '2010-03-12 20:41:30.000000', NULL, 1),
(5901848, 859111, 18505, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2010-03-12 20:43:05.000000', NULL, 1),
(5901849, 859145, 18505, '<td valign="top">I will be interested to see how you did this.  Very creative.</td>', 'I will be interested to see how you did this.  Very creative.', '2010-03-12 20:44:22.000000', NULL, 1),
(5901851, 859221, 18505, '<td valign="top">Just perfect!</td>', 'Just perfect!', '2010-03-12 20:45:28.000000', NULL, 1),
(5901854, 858906, 18505, '<td valign="top">I really like the textures.</td>', 'I really like the textures.', '2010-03-12 20:46:15.000000', NULL, 1),
(5901855, 858572, 18505, '<td valign="top">Not just your usual pretty flower.  I like this.</td>', 'Not just your usual pretty flower.  I like this.', '2010-03-12 20:46:54.000000', NULL, 1),
(5901856, 859124, 100831, '<td valign="top">Wonderful. Just wonderful. Lovely textures and colors. And lines.<br/>"Study lines, draw lots of lines, either from memory or nature, and you will become a good artist." Edgar Degas</td>', 'Wonderful. Just wonderful. Lovely textures and colors. And lines."Study lines, draw lots of lines, either from memory or nature, and you will become a good artist." Edgar Degas', '2010-03-12 20:47:16.000000', NULL, 1),
(5901863, 858572, 63218, '<td valign="top">At first I voted this a 5, but changed my mind (upward), not because of the uber-sharpness but because it reminds me of Rembrandt. Not that Rembrandt would paint bokeh, but you know what I mean. The natural light. The rich shadows. The faithful detail. It could be a little detail of some much larger work.</td>', 'At first I voted this a 5, but changed my mind (upward), not because of the uber-sharpness but because it reminds me of Rembrandt. Not that Rembrandt would paint bokeh, but you know what I mean. The natural light. The rich shadows. The faithful detail. It could be a little detail of some much larger work.', '2010-03-12 20:52:18.000000', NULL, 1),
(5901867, 858917, 63218, '<td valign="top">This grew on me &amp; now I love it.</td>', 'This grew on me & now I love it.', '2010-03-12 20:54:54.000000', NULL, 1),
(5901872, 858940, 63218, '<td valign="top">This could be BW or color, the variety of textures is interesting without being demanding, the composition seems to be settling toward stagnant at first. After a while I decided it is the busiest minimalist comp I''ve ever seen. Adjusting my vote--up.</td>', 'This could be BW or color, the variety of textures is interesting without being demanding, the composition seems to be settling toward stagnant at first. After a while I decided it is the busiest minimalist comp I''ve ever seen. Adjusting my vote--up.', '2010-03-12 20:58:10.000000', NULL, 1),
(5901892, 859183, 108384, '<td valign="top">I am in love with the Lensbaby.  Fantastic shot.</td>', 'I am in love with the Lensbaby.  Fantastic shot.', '2010-03-12 21:17:17.000000', NULL, 1),
(5901895, 858802, 108384, '<td valign="top">This is truly amazing.  If I could vote it would definitely be a 10.</td>', 'This is truly amazing.  If I could vote it would definitely be a 10.', '2010-03-12 21:18:17.000000', NULL, 1),
