(5902064, 859124, 94815, '<td valign="top">Not many photos manage to successfully imitate an Impressionist painting, but this one does - unexpectedly - in both its light and spontaneous spirit.</td>', 'Not many photos manage to successfully imitate an Impressionist painting, but this one does - unexpectedly - in both its light and spontaneous spirit.', '2010-03-12 23:44:44.000000', NULL, 1),
