(5903440, 859028, 113278, '<td valign="top">Love the simplicity of the feather with the reflection on the crumpled background. Would of liked to see the dust spots healed out though.</td>', 'Love the simplicity of the feather with the reflection on the crumpled background. Would of liked to see the dust spots healed out though.', '2010-03-14 09:37:46.000000', NULL, 1),
(5903441, 859179, 68769, '<td valign="top">The mans solitude is poetic..</td>', 'The mans solitude is poetic..', '2010-03-14 09:38:14.000000', NULL, 1),
(5903442, 858912, 114285, '<td valign="top">Ohhh I like this one, very sentimental, especially the reflection on the plate.</td>', 'Ohhh I like this one, very sentimental, especially the reflection on the plate.', '2010-03-14 09:38:28.000000', NULL, 1),
(5903443, 858492, 39850, '<td valign="top">5 - I find the OOF stick at the fore dominates too much, but the hollow and - well everything else that is in focus, is interesting.</td>', '5 - I find the OOF stick at the fore dominates too much, but the hollow and - well everything else that is in focus, is interesting.', '2010-03-14 09:38:34.000000', NULL, 1),
(5903444, 858390, 113278, '<td valign="top">Great tone and texture here. This is an interesting shot. My morbid mind would of liked some blood on the razor and running down the side of the tub but, yeah, I may have issues lol. Good luck.</td>', 'Great tone and texture here. This is an interesting shot. My morbid mind would of liked some blood on the razor and running down the side of the tub but, yeah, I may have issues lol. Good luck.', '2010-03-14 09:39:11.000000', NULL, 1),
(5903445, 859170, 114285, '<td valign="top">Sorry this does nothing for me.</td>', 'Sorry this does nothing for me.', '2010-03-14 09:39:30.000000', NULL, 1),
(5903446, 859248, 113278, '<td valign="top">Great blur and use of the swing to frame the subject. Well done.</td>', 'Great blur and use of the swing to frame the subject. Well done.', '2010-03-14 09:39:46.000000', NULL, 1),
(5903447, 858383, 39850, '<td valign="top">5 - Don''t mind the concept, but given your title, I find the subject and colors don''t gel that well.  There are also some funky gamma things happening in the dark blotches.</td>', '5 - Don''t mind the concept, but given your title, I find the subject and colors don''t gel that well.  There are also some funky gamma things happening in the dark blotches.', '2010-03-14 09:39:48.000000', NULL, 1),
(5903448, 859143, 114285, '<td valign="top">Brilliant.</td>', 'Brilliant.', '2010-03-14 09:39:53.000000', NULL, 1),
(5903450, 858383, 68769, '<td valign="top">most Definitely a gallery type image..</td>', 'most Definitely a gallery type image..', '2010-03-14 09:40:32.000000', NULL, 1),
(5903452, 859221, 114285, '<td valign="top">TOO CUTE.</td>', 'TOO CUTE.', '2010-03-14 09:40:50.000000', NULL, 1),
(5903453, 858813, 113278, '<td valign="top">Interesting use of abstract objects with light. I like how it seems as though her body is almost transparent and it seems as though her ribs are visible like a x-ray.</td>', 'Interesting use of abstract objects with light. I like how it seems as though her body is almost transparent and it seems as though her ribs are visible like a x-ray.', '2010-03-14 09:41:16.000000', NULL, 1),
(5903455, 859035, 114285, '<td valign="top">Sweet and simple, very artistic.</td>', 'Sweet and simple, very artistic.', '2010-03-14 09:41:27.000000', NULL, 1),
(5903456, 859039, 113278, '<td valign="top">I like the simple subject and the (falling snow?) adds to this.</td>', 'I like the simple subject and the (falling snow?) adds to this.', '2010-03-14 09:41:52.000000', NULL, 1),
(5903457, 859197, 114285, '<td valign="top">Could be a winner.</td>', 'Could be a winner.', '2010-03-14 09:42:08.000000', NULL, 1),
(5903458, 858967, 113278, '<td valign="top">Interesting. I like how it seems frozen in time. Simple yet fun.</td>', 'Interesting. I like how it seems frozen in time. Simple yet fun.', '2010-03-14 09:42:17.000000', NULL, 1),
(5903459, 859039, 114285, '<td valign="top">So simple, but so good.</td>', 'So simple, but so good.', '2010-03-14 09:42:31.000000', NULL, 1),
(5903460, 857967, 113278, '<td valign="top">Love the texture and color on this.</td>', 'Love the texture and color on this.', '2010-03-14 09:42:38.000000', NULL, 1),
(5903461, 859021, 113278, '<td valign="top">Love the nice light followed with dark shadow reflection. Nice.</td>', 'Love the nice light followed with dark shadow reflection. Nice.', '2010-03-14 09:43:07.000000', NULL, 1),
(5903462, 859171, 114285, '<td valign="top">Good pic, but overdone in the saturation department.</td>', 'Good pic, but overdone in the saturation department.', '2010-03-14 09:43:25.000000', NULL, 1);
