(5903463, 858667, 114285, '<td valign="top">Not sure what this is,</td>', 'Not sure what this is,', '2010-03-14 09:43:44.000000', NULL, 1),
(5903464, 858551, 113278, '<td valign="top">I really like the textures here and the light and shadows make this pop. Nice work.</td>', 'I really like the textures here and the light and shadows make this pop. Nice work.', '2010-03-14 09:43:46.000000', NULL, 1),
(5903465, 859211, 39850, '<td valign="top">5 - The composition doesn''t appeal to me.</td>', '5 - The composition doesn''t appeal to me.', '2010-03-14 09:44:07.000000', NULL, 1),
(5903466, 859162, 114285, '<td valign="top">I find the background very distracting, but the foreground is very elegant.</td>', 'I find the background very distracting, but the foreground is very elegant.', '2010-03-14 09:44:34.000000', NULL, 1),
(5903467, 857780, 113278, '<td valign="top">I like the nice light coming in with the dreamy fog.</td>', 'I like the nice light coming in with the dreamy fog.', '2010-03-14 09:44:45.000000', NULL, 1),
(5903468, 859246, 39850, '<td valign="top">5 - Seems a bit flat, needing further pp - something going on bottom left.</td>', '5 - Seems a bit flat, needing further pp - something going on bottom left.', '2010-03-14 09:44:51.000000', NULL, 1),
(5903469, 859225, 114285, '<td valign="top">Ohh what a sad sight.</td>', 'Ohh what a sad sight.', '2010-03-14 09:45:05.000000', NULL, 1),
(5903470, 858719, 113278, '<td valign="top">I love the brightness of this and the dreamy feel.</td>', 'I love the brightness of this and the dreamy feel.', '2010-03-14 09:45:13.000000', NULL, 1),
(5903472, 859179, 39850, '<td valign="top">5 - Especially like the duck and the sun, perhaps potential with a variation in cropping and some tweaking in pp.</td>', '5 - Especially like the duck and the sun, perhaps potential with a variation in cropping and some tweaking in pp.', '2010-03-14 09:45:57.000000', NULL, 1),
(5903473, 858600, 113278, '<td valign="top">Love this. The dark feel and the birds then the person with the bright red works well.</td>', 'Love this. The dark feel and the birds then the person with the bright red works well.', '2010-03-14 09:46:17.000000', NULL, 1),
(5903474, 859179, 114285, '<td valign="top">Very very good, great colours.</td>', 'Very very good, great colours.', '2010-03-14 09:46:18.000000', NULL, 1),
(5903475, 858361, 113278, '<td valign="top">Nice light and overall feel on this.</td>', 'Nice light and overall feel on this.', '2010-03-14 09:46:36.000000', NULL, 1),
(5903476, 858425, 113278, '<td valign="top">I like the simplicity of this. The circle and the lines work well together.</td>', 'I like the simplicity of this. The circle and the lines work well together.', '2010-03-14 09:47:16.000000', NULL, 1),
(5903477, 858744, 113278, '<td valign="top">The textures and shadow really makes this nice.</td>', 'The textures and shadow really makes this nice.', '2010-03-14 09:47:35.000000', NULL, 1),
(5903478, 859027, 113278, '<td valign="top">I gave you a low score and want to let you know why. The shot seems well composed and lit and all that but for me it is all just preference and I do not like to look at this one. But now that I am writing this and have given it a bit more time, I still do not care for the subject matter but 1. You are brave to post something like this. 2. It is well done from a technical stand point and 3. I can see this being interpeted as a contemporary piece of art. So from a 1(just because I didn''t like it) I move you up to a 7. Hope you do well but I''d rather not see this on the from page to look at for a week :) Good luck.</td>', 'I gave you a low score and want to let you know why. The shot seems well composed and lit and all that but for me it is all just preference and I do not like to look at this one. But now that I am writing this and have given it a bit more time, I still do not care for the subject matter but 1. You are brave to post something like this. 2. It is well done from a technical stand point and 3. I can see this being interpeted as a contemporary piece of art. So from a 1(just because I didn''t like it) I move you up to a 7. Hope you do well but I''d rather not see this on the from page to look at for a week :) Good luck.', '2010-03-14 09:47:41.000000', NULL, 1),
(5903479, 859108, 114285, '<td valign="top">That looks elegant, is that a dracena, I took a pic like that, for the nature challenge and it looks very similar, to this one.</td>', 'That looks elegant, is that a dracena, I took a pic like that, for the nature challenge and it looks very similar, to this one.', '2010-03-14 09:48:08.000000', NULL, 1),
(5903480, 859078, 113278, '<td valign="top">interesting and different. I like this shot.</td>', 'interesting and different. I like this shot.', '2010-03-14 09:48:20.000000', NULL, 1),
(5903481, 858846, 113278, '<td valign="top">Love the simple feel of this. Very nice.</td>', 'Love the simple feel of this. Very nice.', '2010-03-14 09:48:43.000000', NULL, 1),
(5903482, 859221, 113278, '<td valign="top">This shot is beautiful. Great lighting and composition but for me and just my opinion on fine art this doesn''t seem to fit. I may be way off and maybe this fits Fine Art really well but for me it doesn''t go with what I imagine fine art to be. But it is a stunning photo.<br/> <br/>ETA, I have not been fair to this photo as there was a similar shot that I ended up scoring higher after debating with myself and after coming back again to this one I think it only fair to give this a higher score.</td>', 'This shot is beautiful. Great lighting and composition but for me and just my opinion on fine art this doesn''t seem to fit. I may be way off and maybe this fits Fine Art really well but for me it doesn''t go with what I imagine fine art to be. But it is a stunning photo. ETA, I have not been fair to this photo as there was a similar shot that I ended up scoring higher after debating with myself and after coming back again to this one I think it only fair to give this a higher score.', '2010-03-14 09:48:48.000000', NULL, 1),
(5903483, 859086, 114285, '<td valign="top">It''s very yellow, is something missing here?</td>', 'It''s very yellow, is something missing here?', '2010-03-14 09:49:02.000000', NULL, 1),
