(5904426, 858967, 38032, '<td valign="top">rubik would be proud.</td>', 'rubik would be proud.', '2010-03-14 22:18:04.000000', NULL, 1),
(5904427, 859023, 81362, '<td valign="top">This is my favorite of the challenge: simplicity is outstanding, three abstract yet human form figures contribute a story line, red-orange of alone figure works well with cyan of sky, repeating horizontal elements of clouds and horizon elemets contrast with the upright figures, stark white background excellent, but mostly it just has a lot of appeal independent of analysis of elements.</td>', 'This is my favorite of the challenge: simplicity is outstanding, three abstract yet human form figures contribute a story line, red-orange of alone figure works well with cyan of sky, repeating horizontal elements of clouds and horizon elemets contrast with the upright figures, stark white background excellent, but mostly it just has a lot of appeal independent of analysis of elements.', '2010-03-14 22:18:17.000000', NULL, 1),
(5904428, 859122, 25355, '<td valign="top">This is the one I think deserves a ribbon. I like its quirkiness best of all.</td>', 'This is the one I think deserves a ribbon. I like its quirkiness best of all.', '2010-03-14 22:18:30.000000', NULL, 1),
(5904429, 858875, 38032, '<td valign="top">nice tones and minimal effect</td>', 'nice tones and minimal effect', '2010-03-14 22:18:45.000000', NULL, 1),
(5904432, 859096, 38032, '<td valign="top">Now this is what I was looking for!  I could see a series of photos like this telling the story of a family that isn''t there.  Contemporary work needs intrigue and this certainly has it.  My top pick so far.  9</td>', 'Now this is what I was looking for!  I could see a series of photos like this telling the story of a family that isn''t there.  Contemporary work needs intrigue and this certainly has it.  My top pick so far.  9', '2010-03-14 22:20:26.000000', NULL, 1),
(5904433, 859228, 25355, '<td valign="top">That''s a bad case of blackheads she has, and on her wedding day too.... ;-)<br/>Judi?</td>', 'That''s a bad case of blackheads she has, and on her wedding day too.... ;-)Judi?', '2010-03-14 22:20:49.000000', NULL, 1),
(5904434, 859228, 113900, '<td valign="top">One of my favorites in the entire challenge.  It gives me an uneasy feeling.  The best "fine art" in my opinion should evoke emotions, whether they be joyous emotions or even feelings of dread or bewilderment.  Your photo, IMHO, was one of the top shots in that regard, and is being scored accordingly.  A 10</td>', 'One of my favorites in the entire challenge.  It gives me an uneasy feeling.  The best "fine art" in my opinion should evoke emotions, whether they be joyous emotions or even feelings of dread or bewilderment.  Your photo, IMHO, was one of the top shots in that regard, and is being scored accordingly.  A 10', '2010-03-14 22:20:59.000000', NULL, 1),
(5904436, 859208, 38032, '<td valign="top">The subject works here - I''d like to get closer to tell just a bit more.</td>', 'The subject works here - I''d like to get closer to tell just a bit more.', '2010-03-14 22:21:41.000000', NULL, 1),
(5904437, 858350, 113900, '<td valign="top">I don''t know how others will respond to this, but I love it.  Kudos on the raindrops, nice touch.</td>', 'I don''t know how others will respond to this, but I love it.  Kudos on the raindrops, nice touch.', '2010-03-14 22:22:03.000000', NULL, 1),
(5904440, 859249, 38032, '<td valign="top">Stretching photography  into uncomfortable places.</td>', 'Stretching photography  into uncomfortable places.', '2010-03-14 22:22:30.000000', NULL, 1),
(5904443, 859166, 38032, '<td valign="top">interesting comp and subject.  The photo quality is there and it feels very arty - a bit too self-centered for my taste though but definitely meets the challenge. 6</td>', 'interesting comp and subject.  The photo quality is there and it feels very arty - a bit too self-centered for my taste though but definitely meets the challenge. 6', '2010-03-14 22:23:43.000000', NULL, 1),
