(5904448, 859038, 38032, '<td valign="top">Lovely dog that I''d like to see less processed.</td>', 'Lovely dog that I''d like to see less processed.', '2010-03-14 22:24:40.000000', NULL, 1),
(5904449, 859174, 38032, '<td valign="top">Art goes where some people don''t want to.  An intriguing shot.</td>', 'Art goes where some people don''t want to.  An intriguing shot.', '2010-03-14 22:25:16.000000', NULL, 1),
(5904451, 858694, 81362, '<td valign="top">Enjoyable abstract, red:yellow-orange works well, smooth:radial/circular makes interersting contrast. Makes me think of the sun.</td>', 'Enjoyable abstract, red:yellow-orange works well, smooth:radial/circular makes interersting contrast. Makes me think of the sun.', '2010-03-14 22:26:01.000000', NULL, 1),
(5904452, 859099, 38032, '<td valign="top">I like the subject/s, A tighter crop might make it stronger compositionally.</td>', 'I like the subject/s, A tighter crop might make it stronger compositionally.', '2010-03-14 22:26:15.000000', NULL, 1),
(5904455, 859027, 113900, '<td valign="top">When I first saw this I wanted to score it very low.  I didn''t know how it fit into this challenge and I was just flat out disturbed by it.  Then after a few days of having this image stick in my psyche, I realized that it accomplished one of the fundamental goals of Art: It made me think and took me out of my comfort zone.  Art should always inspire thought, yours definitely did that for me.  It still is unsettling to me, and I imagine that was partially the goal.  For all that I am going to score this shot very highly.  Good job.</td>', 'When I first saw this I wanted to score it very low.  I didn''t know how it fit into this challenge and I was just flat out disturbed by it.  Then after a few days of having this image stick in my psyche, I realized that it accomplished one of the fundamental goals of Art: It made me think and took me out of my comfort zone.  Art should always inspire thought, yours definitely did that for me.  It still is unsettling to me, and I imagine that was partially the goal.  For all that I am going to score this shot very highly.  Good job.', '2010-03-14 22:27:29.000000', NULL, 1),
(5904456, 858824, 38032, '<td valign="top">interesting objects  - perhaps more drama in the lighting would add some mystery to it.</td>', 'interesting objects  - perhaps more drama in the lighting would add some mystery to it.', '2010-03-14 22:28:11.000000', NULL, 1),
(5904457, 859221, 38032, '<td valign="top">Great comp.  Beautiful subjects.</td>', 'Great comp.  Beautiful subjects.', '2010-03-14 22:28:50.000000', NULL, 1),
(5904459, 859244, 38032, '<td valign="top">Feels a bit cold</td>', 'Feels a bit cold', '2010-03-14 22:29:18.000000', NULL, 1),
