INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5905197, 859221, 15711, '<td valign="top">Such a wonderful shot. Congrats on 4th.</td>', 'Such a wonderful shot. Congrats on 4th.', '2010-03-15 09:34:59.000000', NULL, 0),
(5905203, 858282, 23098, '<td valign="top">An interesting image. I liked the comp, it draws you in, nice find and work.</td>', 'An interesting image. I liked the comp, it draws you in, nice find and work.', '2010-03-15 09:36:42.000000', NULL, 0),
(5905208, 858282, 15711, '<td valign="top">I like how the three objects connect to make a triangle. :)</td>', 'I like how the three objects connect to make a triangle. :)', '2010-03-15 09:38:17.000000', NULL, 0),
(5905210, 858390, 15711, '<td valign="top">Get out the Comet cleanser!!  LOL</td>', 'Get out the Comet cleanser!!  LOL', '2010-03-15 09:38:50.000000', NULL, 0),
(5905213, 859124, 15711, '<td valign="top">Sorry this didn''t fare better.  I''m wondering if the background is a bit too busy? I''d have loved it if it was just the guy with the hat.  I still love the painterly quality of it though. :)</td>', 'Sorry this didn''t fare better.  I''m wondering if the background is a bit too busy? I''d have loved it if it was just the guy with the hat.  I still love the painterly quality of it though. :)', '2010-03-15 09:40:02.000000', NULL, 0),
(5905215, 859203, 15711, '<td valign="top">Fantastic contrasts!!!</td>', 'Fantastic contrasts!!!', '2010-03-15 09:40:33.000000', NULL, 0),
(5905217, 859128, 15711, '<td valign="top">This would make a great poster.</td>', 'This would make a great poster.', '2010-03-15 09:40:51.000000', NULL, 0),
(5905218, 858719, 15711, '<td valign="top">Sorry this didn''t fare better.  I stand by my earlier comments. :)</td>', 'Sorry this didn''t fare better.  I stand by my earlier comments. :)', '2010-03-15 09:41:08.000000', NULL, 0),
(5905220, 859217, 15711, '<td valign="top">So sorry this didn''t do better.  I really liked it.</td>', 'So sorry this didn''t do better.  I really liked it.', '2010-03-15 09:41:27.000000', NULL, 0),
(5905235, 858035, 54645, '<td valign="top">Hey, at least it''s better than nature''s recycling!!!</td>', 'Hey, at least it''s better than nature''s recycling!!!', '2010-03-15 09:57:05.000000', NULL, 0),
(5905238, 858694, 38032, '<td valign="top">Sorry for the strange comment.  I was trying to comment on all images but ran out of time. Some of my comments were abridged ;) I thought it was great - and it was tough to see how it was a photo and not digital art.  Not a bad thing by any means. I actually like it more knowing the context / object. <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by tate:</b></div><hr/><i> photo vs image 6 </i></td></tr></table><br/><br/><i>Message edited by author 2010-03-15 09:59:05.</i></td>', 'Sorry for the strange comment.  I was trying to comment on all images but ran out of time. Some of my comments were abridged ;) I thought it was great - and it was tough to see how it was a photo and not digital art.  Not a bad thing by any means. I actually like it more knowing the context / object. Originally posted by tate: photo vs image 6 ', '2010-03-15 09:58:34.000000', '2010-03-15 09:59:05.000000', 0),
(5905239, 858671, 54645, '<td valign="top">I''ve been looking for my head...</td>', 'I''ve been looking for my head...', '2010-03-15 09:58:38.000000', NULL, 0),
(5905246, 858626, 54645, '<td valign="top">Deb said it all. Spring is around the corner!</td>', 'Deb said it all. Spring is around the corner!', '2010-03-15 10:01:31.000000', NULL, 0),
(5905256, 859023, 53814, '<td valign="top">Great entry Sarah! Congratulations!</td>', 'Great entry Sarah! Congratulations!', '2010-03-15 10:10:49.000000', NULL, 0),
(5905260, 859027, 38032, '<td valign="top">I actually reviewed this and was unable to post it on my iPhone so I saved it for later.  I rewrote it when actually posting and wanted to give you more but sometimes words are not enough.<br/> <br/>It was the one photo that I kept thinking about.<br/> <br/>You are right about "contemporary art" being the "now" rather than "modern" which was decades ago  so I''m glad they included "contemporary" in the challenge description.  <br/> <br/>I love the story and I love that this is a shot that reflects the reality of your life. Thank you so much for posting all the information - truly moving and you are an artist that I would aspire to emulate. <br/> <br/>I can''t imaging how this wouldn''t play well by the jury  and as you know I gave it the highest score possible - the only photo I gave a 10.<br/></td>', 'I actually reviewed this and was unable to post it on my iPhone so I saved it for later.  I rewrote it when actually posting and wanted to give you more but sometimes words are not enough. It was the one photo that I kept thinking about. You are right about "contemporary art" being the "now" rather than "modern" which was decades ago  so I''m glad they included "contemporary" in the challenge description.   I love the story and I love that this is a shot that reflects the reality of your life. Thank you so much for posting all the information - truly moving and you are an artist that I would aspire to emulate.  I can''t imaging how this wouldn''t play well by the jury  and as you know I gave it the highest score possible - the only photo I gave a 10.', '2010-03-15 10:16:35.000000', NULL, 0),
(5905261, 857872, 112739, '<td valign="top">This was the first image in the challenge that made me stop and look. I think it should have been in the top 3, but congrats on the 5th. The image really executes the feeling of being on the reverse side of reality for me.</td>', 'This was the first image in the challenge that made me stop and look. I think it should have been in the top 3, but congrats on the 5th. The image really executes the feeling of being on the reverse side of reality for me.', '2010-03-15 10:17:01.000000', NULL, 0),
(5905267, 858694, 2553, '<td valign="top">Absolutely beautiful!  <br/> <br/>It is my feeling that Fine Art goes outside the bounds of "is it a photo or is it digital art?". It simply doesn''t matter.  Fine Art is ART no matter the form.  <br/> <br/>Fine Art should answer one simple question: Would I hang this on my wall and enjoy viewing it?<br/> <br/>In the case of your image my answer to that question is absolutely YES! It''s a well-done image on so many levels.  If I had had a chance to vote, this would have been a unequivocal, solid 10.</td>', 'Absolutely beautiful!   It is my feeling that Fine Art goes outside the bounds of "is it a photo or is it digital art?". It simply doesn''t matter.  Fine Art is ART no matter the form.   Fine Art should answer one simple question: Would I hang this on my wall and enjoy viewing it? In the case of your image my answer to that question is absolutely YES! It''s a well-done image on so many levels.  If I had had a chance to vote, this would have been a unequivocal, solid 10.', '2010-03-15 10:22:13.000000', NULL, 0),
(5905272, 857872, 2553, '<td valign="top">Splendid image!  Shocked that it wasn''t in the top 3.  It really nails the spirit of the challenge for me, and this REALLY WOULD make an amazing fine art piece - I can totally see it for decorating large wall space.</td>', 'Splendid image!  Shocked that it wasn''t in the top 3.  It really nails the spirit of the challenge for me, and this REALLY WOULD make an amazing fine art piece - I can totally see it for decorating large wall space.', '2010-03-15 10:29:54.000000', NULL, 0),
(5905274, 859108, 63495, '<td valign="top">very nice Deb. i love the feeling it creates</td>', 'very nice Deb. i love the feeling it creates', '2010-03-15 10:35:55.000000', NULL, 0),
(5905303, 859027, 113278, '<td valign="top">I am glad I bumped up the score I originally gave this. After reading the story behind it and seeing all of the comments on this, I really think this should be the winner hands down. This is an image that has stuck with me and it is one I won''t likely soon forget. Well done.</td>', 'I am glad I bumped up the score I originally gave this. After reading the story behind it and seeing all of the comments on this, I really think this should be the winner hands down. This is an image that has stuck with me and it is one I won''t likely soon forget. Well done.', '2010-03-15 11:14:05.000000', NULL, 0),
(5905322, 859128, 61961, '<td valign="top">Nice graphic impact.  I would never have guessed this was yours, Steve.  Interesting to see your entry in the challenge idea you championed!  Technically, I''m curious to know how big was the sea horse?  The ones I''ve seen are generally about half an inch "tall."</td>', 'Nice graphic impact.  I would never have guessed this was yours, Steve.  Interesting to see your entry in the challenge idea you championed!  Technically, I''m curious to know how big was the sea horse?  The ones I''ve seen are generally about half an inch "tall."', '2010-03-15 11:29:43.000000', NULL, 0),
(5905327, 859033, 49109, '<td valign="top">Good work and very elaborate setup.  I never thought of a double exposure. Should have placed higher IMO.</td>', 'Good work and very elaborate setup.  I never thought of a double exposure. Should have placed higher IMO.', '2010-03-15 11:35:41.000000', NULL, 0),
(5905330, 858654, 72103, '<td valign="top">brilliantly bizzare, nice work mate............</td>', 'brilliantly bizzare, nice work mate............', '2010-03-15 11:43:41.000000', NULL, 0),
(5905332, 859023, 72103, '<td valign="top">brilliant, love it</td>', 'brilliant, love it', '2010-03-15 11:46:12.000000', NULL, 0),
(5905365, 858967, 111123, '<td valign="top">Great picture, I would have liked it more with a smaller crop. But I love the background &amp; how the cube looks like it''s floating! Good job.</td>', 'Great picture, I would have liked it more with a smaller crop. But I love the background & how the cube looks like it''s floating! Good job.', '2010-03-15 12:19:46.000000', NULL, 0),
(5905373, 858600, 32767, '<td valign="top">Well, I''m honestly not that good at commenting on this stuff but I did give it an 8 and have to say I guess that put it somewhere in my Top 15-20 and I really didn''t have number 1 pick in this Challenge. Simply said, it''s a really beautiful scene and that rested quite well with me. Cheers on the Ribbon...super, well deserved.</td>', 'Well, I''m honestly not that good at commenting on this stuff but I did give it an 8 and have to say I guess that put it somewhere in my Top 15-20 and I really didn''t have number 1 pick in this Challenge. Simply said, it''s a really beautiful scene and that rested quite well with me. Cheers on the Ribbon...super, well deserved.', '2010-03-15 12:24:48.000000', NULL, 0),
(5905378, 859221, 65319, '<td valign="top">Oh Karen!  Congrats on 4th place!  This one got a 9 from me!  So, tender and beautiful!  Well done!</td>', 'Oh Karen!  Congrats on 4th place!  This one got a 9 from me!  So, tender and beautiful!  Well done!', '2010-03-15 12:28:00.000000', NULL, 0),
