INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6029350, 859027, 117831, '<td valign="top">I realize that this is from an old challenge but I have been scrolling thru images and came across this one. Before I even read your description I had tears in my eyes and rolling down my cheeks. This image , this peice of art, provoked serious emotion and no words needed to be spoken. This photo reminded me of my father, I commend your courage to share your story with us. So many people hide behind walls of fakeness and non reality. They hide their ailments and tribulations for fear that others will judge them. I praise you for wanting to show the world. I praise you for having the confidence, the courage, and the desire.</td>', 'I realize that this is from an old challenge but I have been scrolling thru images and came across this one. Before I even read your description I had tears in my eyes and rolling down my cheeks. This image , this peice of art, provoked serious emotion and no words needed to be spoken. This photo reminded me of my father, I commend your courage to share your story with us. So many people hide behind walls of fakeness and non reality. They hide their ailments and tribulations for fear that others will judge them. I praise you for wanting to show the world. I praise you for having the confidence, the courage, and the desire.', '2010-05-27 03:07:33.000000', NULL, 0),
(6046112, 859023, 73056, '<td valign="top">Sarah, I just want to say you are becoming the master of beautiful, artistic blurs as well as beautiful landscapes. I am really enjoying seeing the growth in your portfolio. You''re becoming a fantastic photographer! There are plenty of ribbons ahead for you!<br/><br/><i>Message edited by author 2010-06-08 12:26:30.</i></td>', 'Sarah, I just want to say you are becoming the master of beautiful, artistic blurs as well as beautiful landscapes. I am really enjoying seeing the growth in your portfolio. You''re becoming a fantastic photographer! There are plenty of ribbons ahead for you!', '2010-06-08 02:24:24.000000', '2010-06-08 13:26:30.000000', 0),
(6061657, 859226, 56744, '<td valign="top">Tim,<br/>This is an amazing photograph that stands out of the DPC''s world. This is really ART and I think you are much better doing really good stuff than trying to please the basic DPCer''s taste. I love it. Congrats for this amazing example of fine photography.<br/></td>', 'Tim,This is an amazing photograph that stands out of the DPC''s world. This is really ART and I think you are much better doing really good stuff than trying to please the basic DPCer''s taste. I love it. Congrats for this amazing example of fine photography.', '2010-06-18 08:26:09.000000', NULL, 0),
(6100131, 858891, 4767, '<td valign="top">Did the Disney security force harass you about using a tripod?  I was shooting very near this vantage point in the early evening and THREE security guards came to tell me that hand-held photography was ok, but NO tripods allowed. <br/> <br/>Nice image.  Gives a good feel of the building.<br/> <br/></td>', 'Did the Disney security force harass you about using a tripod?  I was shooting very near this vantage point in the early evening and THREE security guards came to tell me that hand-held photography was ok, but NO tripods allowed.  Nice image.  Gives a good feel of the building. ', '2010-07-21 18:19:19.000000', NULL, 0),
(6100173, 858891, 112972, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by f-32:</b></div><hr/><i> Did the Disney security force harass you about using a tripod?  I was shooting very near this vantage point in the early evening and THREE security guards came to tell me that hand-held photography was ok, but NO tripods allowed. <br/> <br/>Nice image.  Gives a good feel of the building. </i></td></tr></table> <br/> <br/>Same here.  They said "no tripods", so I took all my shots handheld including this one.</td>', 'Originally posted by f-32: Did the Disney security force harass you about using a tripod?  I was shooting very near this vantage point in the early evening and THREE security guards came to tell me that hand-held photography was ok, but NO tripods allowed.  Nice image.  Gives a good feel of the building.   Same here.  They said "no tripods", so I took all my shots handheld including this one.', '2010-07-21 18:58:55.000000', NULL, 0),
